/// <summary>
/// AVA_009012_RouteOprCard_Report
/// </summary>

class AVAProdRunMapController extends SrsReportRunController
{

    public ProdParmRelease            prodParmRelease;
    public ProdTable                  prodTable;
    public ProdParmStartUp            prodParmStartup;
    public boolean                    printReference;
}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_args">_args</param>
public static void main(Args _args)
{
    AVAProdRunMapController controller = new AVAProdRunMapController();
    ProdTable prodTable = _args.record() as prodTable;
    JmgProdParametersDim jmgProdParametersDim = JmgProdParametersDim::find(prodTable.InventDimId);
    if (jmgProdParametersDim.AVAReduceProdRunMapReport)
    {
        controller.parmReportName(ssrsReportStr(AVAProdRunMap, Report_ReducedLines));
    }
    else
    {
        controller.parmReportName(ssrsReportStr(AVAProdRunMap, Report));
    }
    controller.parmArgs(_args);
    controller.parmProdTable(prodTable);
    controller.startOperation();
}

/// <summary>
/// designed from AVA
/// </summary>
protected void prePromptModifyContract()
{
    AVAProdRunMapContract contract = this.parmReportContract().parmRdpContract() as AVAProdRunMapContract;

    if(prodTable)
    {
        contract.parmProdId(prodTable.ProdId);
    }
    if (this.printFromProdUpd())
    {
        this.parmShowDialog(false);
        this.getPrintReference();
        contract.parmPrintReferences(printReference);
        if (conLen(this.printDestinationFromProdUpd()) !=0 )
        {
            SrsReportDataContract dataContract = this.parmReportContract();
            dataContract.parmPrintSettings(new SRSPrintDestinationSettings(this.printDestinationFromProdUpd()));
        }
    }
}

/// <summary>
/// designed from AVA
/// </summary>
void getPrintReference()
{
    if (prodParmRelease)
    {
        printReference = prodParmRelease.AVAPrintReferenceRunMap;
    }
    if (prodParmStartup)
    {
        printReference =  prodParmStartup.AVAPrintReferenceRunMap;
    }
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_printReference">_printReference</param>
/// <returns>boolean</returns>
boolean parmPrintReference(boolean  _printReference = printReference)
{
    printReference = _printReference;
    return printReference;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_prodTable">_prodTable</param>
/// <returns>ProdTable</returns>
public ProdTable   parmProdTable(ProdTable _prodTable = prodTable)
{
    prodTable       = _prodTable;
    return ProdTable;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_prodParmRelease">_prodParmRelease</param>
/// <returns>ProdParmRelease</returns>
public ProdParmRelease parmProdParmRelease(ProdParmRelease     _prodParmRelease)
{
    ProdParmRelease = _prodParmRelease;
    return ProdParmRelease;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_prodParmStartup">_prodParmStartup</param>
/// <returns>_prodParmStartup</returns>
public ProdParmStartup parmProdParmStartUp(ProdParmStartUp _prodParmStartup)
{
    prodParmStartup = _prodParmStartup;
    return prodParmStartup;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_prodParmRelease">_prodParmRelease</param>
public static void constructFromProdUpdRelease(ProdParmRelease     _prodParmRelease)
{
    AVAProdRunMapController  controller =  new AVAProdRunMapController();
    ProdTable prodTable = _prodParmRelease.prodTable();
    controller.parmReportName(ssrsReportStr(AVAProdRunMap, Report));
    controller.parmProdTable(prodTable);
    controller.parmProdParmRelease(_prodParmRelease);
    controller.startOperation();
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_prodParmStartUp">ProdParmStartUp</param>
public static void constructFromProdUpdStartup(ProdParmStartUp     _prodParmStartUp)
{
    AVAProdRunMapController  controller =  new AVAProdRunMapController();
    ProdTable prodTable = _prodParmStartUp.prodTable();
    controller.parmReportName(ssrsReportStr(AVAProdRunMap, Report));
    controller.parmProdTable(prodTable);
    controller.parmProdParmStartUp(_prodParmStartUp);
    controller.startOperation();
}

/// <summary>
/// desigend from AVA
/// </summary>
/// <returns>container</returns>
container  printDestinationFromProdUpd()
{
    container printDestinCont;
    if (prodParmRelease)
    {
        printDestinCont =  prodParmRelease.AVASetupPrintProdRunMap;
    }
    else if (prodParmStartup)
    {
        printDestinCont =  prodParmStartup.AVASetupPrintProdRunMap;
    }
    return printDestinCont;
}

/// <summary>
///   designed from AVA
/// </summary>
/// <returns>boolean</returns>
boolean printFromProdUpd()
{
    return prodParmRelease.RecId || prodParmStartup.RecId;
}

/// <summary>
/// designed from AVA
/// </summary>
public void runReport()
{
    if(prodTable)
    {
        prodTable.reread();
        prodTable.AVAProdRunMapQty += 1;
        ttsbegin;
        prodTable.selectForUpdate(true);
        prodTable.doUpdate();
        ttscommit;
    }
    super();

    AVAProdRunMapContract contract = this.parmReportContract().parmRdpContract() as AVAProdRunMapContract;
    if (contract.parmPrintReferences())
    {
        AVAPrintProdAttachment::constructFromProduction(prodTable,this.parmReportContract().parmPrintSettings().pack());
    }
}
